// Dev-only fixture generator: renders question-tool.ts's picker in edit mode
// via the real pi-tui `Editor.render()`, at widths 42/80/120, and writes
// test/fixtures/picker/edit-*.txt plus edit-*.expected.json.
//
// The fixtures are regenerated by running this script (`node --import tsx
// pi/test/render-picker-fixtures.ts`); they are never hand-authored. The
// Python port (test/test_herdr_picker.py) reads them back and asserts its
// parse_edit_mode agrees, and a separate test fails if a committed fixture
// differs from a fresh render.
//
// The picker layout below is the same shape question-tool.ts draws (full-width
// accent rules, single-space header/question prefix, 2-column option prefix,
// 5-space description prefix, "Your answer:" label, editor block prefixed by a
// single space, edit footer). Only the editor block goes through the real
// Editor.render() -- that is the part a hand-authored string would get wrong.

import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { Editor, type EditorTheme, visibleWidth, wrapTextWithAnsi } from "@earendil-works/pi-tui";

const FIXTURE_DIR = join(import.meta.dirname, "../../test/fixtures/picker");

const OTHER_LABEL = "Something else (type it)";
const MARKER = "✎";

// Same shape as question-tool.ts's editorTheme, but plain (no ANSI) so the
// captured text is exactly what a pane read --source recent-unwrapped returns.
const plainTheme: EditorTheme = {
  borderColor: (s) => s,
  selectList: {
    selectedPrefix: (s) => s,
    selectedText: (s) => s,
    description: (s) => s,
    scrollInfo: (s) => s,
    noMatch: (s) => s,
  },
};

interface FixtureSpec {
  width: number;
  text: string;
  terminalRows: number;
  name: string;
}

function addWrappedWithPrefix(lines: string[], prefix: string, text: string, width: number): void {
  const prefixWidth = visibleWidth(prefix);
  if (prefixWidth >= width) {
    lines.push(...wrapTextWithAnsi(prefix + text, width));
    return;
  }
  const wrapped = wrapTextWithAnsi(text, width - prefixWidth);
  const continuationPrefix = " ".repeat(prefixWidth);
  wrapped.forEach((wrappedLine, i) => {
    lines.push(`${i === 0 ? prefix : continuationPrefix}${wrappedLine}`);
  });
}

/** Strip the fake cursor's inverse-video ANSI markers, leaving plain text --
 * recent-unwrapped's contract. The plain theme emits no other ANSI. */
function stripAnsi(text: string): string {
  return text.split("\x1b[7m").join("").split("\x1b[0m").join("");
}

/** Render one edit-mode picker at a width; return its plain-text lines. */
function renderEditPicker(width: number, text: string, terminalRows: number): string[] {
  const header = "Land";
  const question = "Commit these changes?";
  const options = [
    { label: "Yes, commit (Recommended)", description: "Commit the staged changes now." },
    { label: "No, don't commit", description: "Leave them uncommitted." },
    { label: OTHER_LABEL, description: "Answer in your own words instead.", isOther: true },
  ];
  // The OTHER option is the one selected when edit mode is entered; it is the
  // marked option and carries the trailing ✎.
  const markedIndex = options.length - 1;

  const tui = {
    terminal: { rows: terminalRows },
    requestRender() {},
  } as unknown as ConstructorParameters<typeof Editor>[0];
  const editor = new Editor(tui, plainTheme);
  editor.setText(text);

  const lines: string[] = [];
  lines.push("─".repeat(width));
  addWrappedWithPrefix(lines, " ", header, width);
  addWrappedWithPrefix(lines, " ", question, width);
  lines.push("");
  options.forEach((option, i) => {
    const highlighted = i === markedIndex;
    const prefix = highlighted ? "> " : "  ";
    const label = `${i + 1}. ${option.label}${option.isOther ? ` ${MARKER}` : ""}`;
    addWrappedWithPrefix(lines, prefix, label, width);
    addWrappedWithPrefix(lines, "     ", option.description, width);
  });
  lines.push("");
  addWrappedWithPrefix(lines, " ", "Your answer:", width);
  for (const line of editor.render(Math.max(1, width - 2))) {
    lines.push(` ${line}`);
  }
  lines.push("");
  addWrappedWithPrefix(lines, " ", "Enter to submit • Esc to go back", width);
  lines.push("─".repeat(width));
  return lines.map(stripAnsi);
}

function isComplete(lines: string[]): boolean {
  const labelIdx = lines.findIndex((l) => l.includes("Your answer:"));
  const top = lines[labelIdx + 1] ?? "";
  const bottom = lines.find((l, i) => i > labelIdx + 1 && l.startsWith(" ─")) ?? "";
  // Complete iff both borders are present and are plain dash runs (no scroll
  // indicator "↑/↓ N more").
  const plain = (l: string) => /^ ─{3,}\s*$/.test(l);
  return plain(top) && plain(bottom);
}

function render(spec: FixtureSpec) {
  const lines = renderEditPicker(spec.width, spec.text, spec.terminalRows);
  const text = `${lines.join("\n")}\n`;
  const expected = {
    options: ["Yes, commit (Recommended)", "No, don't commit", OTHER_LABEL],
    markedIndex: 3,
    editorText: spec.text,
    complete: isComplete(lines),
  };
  writeFileSync(join(FIXTURE_DIR, `${spec.name}.txt`), text, "utf-8");
  writeFileSync(
    join(FIXTURE_DIR, `${spec.name}.expected.json`),
    `${JSON.stringify(expected, null, 2)}\n`,
    "utf-8",
  );
  return { name: spec.name, lines: lines.length, complete: expected.complete };
}

const LONG_TEXT =
  "Foreman review: read the feedback file at the recorded path and act on it before retrying the send-back exactly as written.";
const LONGEST_ALLOWED = "x".repeat(120);
const OVER_LONG = "z".repeat(600);

const specs: FixtureSpec[] = [
  { name: "edit-42", width: 42, text: "", terminalRows: 40 },
  { name: "edit-42-wrapped", width: 42, text: LONG_TEXT, terminalRows: 40 },
  { name: "edit-80", width: 80, text: LONG_TEXT, terminalRows: 40 },
  { name: "edit-120-longest", width: 120, text: LONGEST_ALLOWED, terminalRows: 40 },
  { name: "edit-42-scrolled", width: 42, text: OVER_LONG, terminalRows: 40 },
];

if (process.argv.includes("--check")) {
  // Check mode: re-render and diff against the committed files, write nothing.
  let failed = false;
  for (const spec of specs) {
    const lines = renderEditPicker(spec.width, spec.text, spec.terminalRows);
    const committed = readFileSync(join(FIXTURE_DIR, `${spec.name}.txt`), "utf-8").trim();
    const fresh = `${lines.join("\n")}\n`.trim();
    if (committed !== fresh) {
      failed = true;
      process.stderr.write(
        `[render-picker-fixtures] ${spec.name}.txt differs from a fresh render\n`,
      );
    }
  }
  if (failed) process.exit(1);
  process.stdout.write(
    `[render-picker-fixtures] ${specs.length} edit fixtures match fresh renders\n`,
  );
} else {
  const summary = specs.map(render);
  process.stdout.write(
    `[render-picker-fixtures] wrote ${summary.length} fixtures: ` +
      summary.map((s) => `${s.name} (${s.complete ? "complete" : "scrolled"})`).join(", ") +
      "\n",
  );
}
